script:
frappe.ui.form.on("Project", {
    validate: function(frm) {
        var participants = [];
        var userGroupsProcessed = 0;
        var userGroupCount = frm.doc.custom_ts_details.filter(d => d.pt_participant_type === "User Group").length;

        // Сначала получаем текущих расшаренных пользователей
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "DocShare",
                filters: {
                    share_doctype: "Project",
                    share_name: frm.doc.name
                },
                fields: ["user"]
            },
            callback: function(response) {
                var existingShares = response.message.map(share => share.user);
                
                if (userGroupCount === 0) {
                    processUsers(frm, existingShares);
                } else {
                    processUserGroups(frm, existingShares);
                }
            }
        });
    }
});

function processUsers(frm, existingShares) {
    var participants = [];
    $.each(frm.doc.custom_ts_details, function(i, d) {
        if (d.pt_participant_type === "User") {
            participants.push(d.pt_participant);
        }
    });
    addParticipantsToProject(participants, frm, existingShares);
}

function processUserGroups(frm, existingShares) {
    var participants = [];
    var userGroupsProcessed = 0;
    var userGroupCount = frm.doc.custom_ts_details.filter(d => d.pt_participant_type === "User Group").length;

    $.each(frm.doc.custom_ts_details, function(i, d) {
        if (d.pt_participant_type === "User") {
            participants.push(d.pt_participant);
        }
        if (d.pt_participant_type === "User Group") {
            frappe.call('frappe.client.get', {
                doctype: 'User Group',
                filters: { name: d.pt_participant },
                fieldname: ['user_group_members']
            }).then(function(response) {
                var userGroupMembers = response.message.user_group_members;
                $.each(userGroupMembers, function(index, user) {
                    participants.push(user.user);
                });
                userGroupsProcessed++;
                if (userGroupsProcessed === userGroupCount) {
                    addParticipantsToProject(participants, frm, existingShares);
                }
            });
        }
    });
}

function addParticipantsToProject(participants, frm, existingShares) {
    let uniqueParticipants = [...new Set(participants)]; // Уникальные участники
    
    // Фильтруем только тех, кто еще не расшарен
    let newParticipants = uniqueParticipants.filter(
        participant => !existingShares.includes(participant)
    );

    // Добавляем только новых участников
    newParticipants.forEach(participant => {
        frappe.call({
            method: 'frappe.share.add',
            args: {
                doctype: 'Project',
                name: frm.doc.name,
                user: participant,
                share: 1,
                read: 1
            },
            callback: function(response) {
                if (!response.exc) {
                    frappe.show_alert({
                        message: __("Добавлен доступ для {0}", [participant]),
                        indicator: 'green'
                    }, 3);
                }
            }
        });
    });
    
    // Можно добавить логику для удаления старых шарингов при необходимости
    // removeOldShares(frm, uniqueParticipants, existingShares);
}
